#include "cryptoutils.h"
int main(void){unsigned long long p=23,g=5,a=6,b=15;unsigned long long A=cu_modpow(g,a,p),B=cu_modpow(g,b,p),ka=cu_modpow(B,a,p),kb=cu_modpow(A,b,p);printf("Toy Diffie-Hellman example: prime p=%llu, public generator g=%llu\nAlice secret x=%llu, sends g^x mod p = %llu\nBob secret y=%llu, sends g^y mod p = %llu\nAlice computes B^x mod p = %llu; Bob computes A^y mod p = %llu\n",p,g,a,A,b,B,ka,kb);printf("If instead they send x^g and y^g, Alice gets (y^g)^x and Bob gets (x^g)^y; these are not generally equal, so the protocol fails.\n");puts("This tiny example is only for learning; real DH needs large standardized groups and authenticated key exchange to resist man-in-the-middle attacks.");return 0;}
